/// <summary>
///     The <c>AVADirPartyQuickCreateFormFrm_AVALEAMobileDS_Extension</c> class is the extension for <c>DirPartyQuickCreateForm</c>
/// </summary>
[ExtensionOf(FormDatasourceStr(DirPartyQuickCreateForm, AVALogisticsElectronicAddressMobile))]
final class AVADirPartyQuickCreateFormFrm_AVALEAMobileDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>written</c> method.
/// </summary>
public void written()
{
    next written();

    element.electronicAddressWrite(element.AVALogisticsElectronicAddressMobile);
}

/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean retVal = true;

    /*
    // validateWrite() and write() do not need next-call in COC to avoid error messages
    retVal = next validateWrite(); 
    */
    retVal = true;

    return retVal;
}

/// <summary>
///    AVA <c>writing</c> method.
/// </summary>
public void writing()
{
    LogisticsElectronicAddress locBuffer;

    next writing();

    locBuffer               = element.AVALogisticsElectronicAddressMobile;
    locBuffer.Type          = LogisticsElectronicAddressMethodType::Phone;
    locBuffer.Description   = strFmt("@SYS82282", "@SYS27784");
    locBuffer.IsPrimary     = true;
    locBuffer.IsMobilePhone = true;



    element.setElectronicAddressLocation();
}

public void initValue()
{
    next initValue();
    LogisticsElectronicAddress locBuffer;

    locBuffer               = element.AVALogisticsElectronicAddressMobile;
    locBuffer.IsMobilePhone = true;

    FormRun  formRun = this.formRun();

    Args   elementArgs = formRun.args();

    if (elementArgs.caller() is FormRun && elementArgs.caller() && elementArgs.parmObject() is FormControl)
    {
        FormControl  callerControler = elementArgs.parmObject() as FormControl;

        if (callerControler.name()  == formControlStr(SalesTable, AVAEDIBuyerContactCreate))
        {
            FormRun             callerFormRun = elementArgs.caller();
            FormDataSource      ediAddressDS  = callerFormRun.dataSource(formDataSourceStr(SalesTable,AVAEDIAddress));
            if (ediAddressDS)
            {
                AVAEDIAddress       ediAddress = ediAddressDS.cursor();

                if(ediAddress.EDIAddressType == AVAEDIAddressType::Buyer)
                {
                    locBuffer.Locator  = ediAddress.ContactPersonPhone;
                }
            }
        }                                                            

    }
}
